112: // formatEntry renders a single ledger line for the given entry.
113: func formatEntry(entry Entry, symbol string, l locale) (string, error) {
114: 	date, err := formatDate(entry.Date, l.dateLayout)
115: 	if err != nil {
116: 		return "", err
117: 	}
118: 	amount := padLeft(l.formatAmount(symbol, entry.Change), amountColumnWidth)
119: 	return date + " | " +
120: 		padRight(truncate(entry.Description, descriptionWidth), descriptionWidth) + " | " +
121: 		amount + "\n", nil
122: }
