124: // formatDate parses an entry date and renders it with the given layout.
125: func formatDate(date, layout string) (string, error) {
126: 	t, err := time.Parse(entryDateLayout, date)
127: 	if err != nil {
128: 		return "", errInvalidDate
129: 	}
130: 	return padRight(t.Format(layout), dateColumnWidth), nil
131: }
