133: // formatNumber formats a non-negative amount in cents with the given
134: // thousands and decimal separators, e.g. formatNumber(123456, ",", ".")
135: // returns "1,234.56".
136: func formatNumber(cents int, thousandsSep, decimalSep string) string {
137: 	dollars := strconv.Itoa(cents / 100)
138: 	var grouped strings.Builder
139: 	for i, r := range dollars {
140: 		// Insert a separator before a digit that starts a new group of
141: 		// three, counting from the right.
142: 		if i > 0 && (len(dollars)-i)%3 == 0 {
143: 			grouped.WriteString(thousandsSep)
144: 		}
145: 		grouped.WriteRune(r)
146: 	}
147: 	return grouped.String() + decimalSep + fmt.Sprintf("%02d", cents%100)
148: }
