150: // truncate shortens s to at most width runes, replacing the omitted
151: // characters with an ellipsis.
152: func truncate(s string, width int) string {
153: 	if utf8.RuneCountInString(s) <= width {
154: 		return s
155: 	}
156: 	runes := []rune(s)
157: 	return string(runes[:width-len(ellipsis)]) + ellipsis
158: }
159: 
160: // padRight pads s with spaces on the right until it is width runes long.
161: func padRight(s string, width int) string {
162: 	return s + strings.Repeat(" ", width-utf8.RuneCountInString(s))
163: }
164: 
165: // padLeft pads s with spaces on the left until it is width runes long.
166: func padLeft(s string, width int) string {
167: 	return strings.Repeat(" ", width-utf8.RuneCountInString(s)) + s
168: }
